// Las piezas con "lista": true, con su clave de semana (p. ej. "pieza:matchday-2026-10-19")
return Object.values($input.first().json.piezas || {})
  .filter(p => p.lista)
  .map(pieza => ({ json: { clave: `pieza:${pieza.tipo}-${pieza.semana}`, pieza } }));

// Un elemento por aviso (cambios.json puede no existir aún: entonces no hay avisos).
// Solo los de los 2 últimos días: si la memoria está vacía (p. ej. recién creada), no se repite lo antiguo.
const desde = Date.now() - 2 * 864e5;
return ($input.first().json.avisos || [])
  .filter(a => !a.detectado || new Date(a.detectado) >= desde)
  .map(a => ({ json: { id: a.id, texto: a.texto, clave: `aviso:${a.id}` } }));

// Foto del post + petición del texto. La línea «🆔» dice qué pieza es: al responder, el bot la lee
// de ahí (así no tiene que recordar nada).
// En un carrusel, antes van sus imágenes (para verlo entero) y la portada la última: a ella se responde.
// La portada lleva el botón «🚫 Esta semana no» para que no se vuelva a ofrecer.
return $input.all().flatMap(item => {
  const p = item.json.pieza;
  const falta = (p.faltan || []).length ? `\n⚠️ Ojo, falta: ${p.faltan.join('; ')}` : '';
  const resto = (p.carrusel || []).slice(1);
  const carrusel = resto.map((foto, i) => ({ json: { accion: 'foto_carrusel', foto, texto: `${p.nombre} · carrusel ${i + 2}/${resto.length + 1}` } }));
  return [...carrusel, { json: { accion: 'pedir_texto', foto: p.post,
    texto: `${p.nombre} lista para publicar ✅${falta}${item.json.aviso ? '\n' + item.json.aviso : ''}` + (resto.length ? `\n📚 Carrusel de ${resto.length + 1} imágenes (esta es la portada; las demás, encima).` : '') +
      `\n\n✍️ RESPONDE A ESTA FOTO (mantén pulsado → Responder) con el texto de la publicación.` +
      `\n🚫 Si esta semana no se publica, pulsa el botón y no volverá a salir.\n🆔 ${p.tipo}`,
    boton: '🚫 Esta semana no', dato: `des:${p.tipo}:${p.semana}` } }];
});

// Decide qué hacer con cada mensaje o botón del grupo. Sin IA: lo que hace falta saber va escrito en los
// propios mensajes del bot («🆔 pieza» y el texto entre las rayas). Lo único que recuerda es si una pieza de
// esta semana ya está publicada o descartada (tabla memoria_ortuella).
const upd = $('Telegram (grupo)').first().json;
const piezas = $('Leer ultimo.json (bot)').first().json.piezas || {};
const MEMORIA = Object.fromEntries($('Leer la memoria (bot)').all().map(i => i.json).filter(f => f.clave).map(f => [f.clave, f.estado]));
const marca = p => MEMORIA[`pieza:${p.tipo}-${p.semana}`];   // 'publicada', 'descartada' o nada
const apuntar = (p, estado) => ({ accion: 'memoria', clave: `pieza:${p.tipo}-${p.semana}`, estado });
const PEDIR = { ordutegia: 'horarios', emaitzak: 'resultados', matchday: 'match day A', 'matchday-b': 'match day B', sailkapena: 'clasificacion' };
// Amistosos apuntados (datos-amistosos.js de la web; vacío si aún no existe)
const AMISTOSOS = (() => { try { const t = String($('Leer amistosos (bot)').first().json.data || ''); return JSON.parse(t.slice(t.indexOf('['), t.lastIndexOf(']') + 1)); } catch (e) { return []; } })();
const CATS = { primer: 'SENIOR A', b: 'SENIOR B', juvenil: 'JUVENIL', cadete: 'CADETE', infantil: 'INFANTIL', alevin: 'ALEVÍN' };
const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const fechaLarga = iso => { const d = new Date(iso + 'T12:00:00'); return `${DIAS[d.getDay()]} ${iso.slice(8)}/${iso.slice(5, 7)}/${iso.slice(0, 4)}`; };
const nombreNuestro = id => ({ b: 'Ortuella B' })[id] || 'Ortuella';
const marcador = (a, gl, gv) => a.casa ? `${nombreNuestro(a.equipo)} ${gl} - ${gv} ${a.rival}` : `${a.rival} ${gl} - ${gv} ${nombreNuestro(a.equipo)}`;
const salir = (...cosas) => cosas.map(json => ({ json }));
const mensaje = texto => ({ accion: 'mensaje', texto });
const RAYA = '────────────';
const pieza = tipo => piezas[tipo];
const NOMBRE = { ordutegia: 'Horarios (ORDUTEGIA)', emaitzak: 'Resultados (EMAITZAK)',
                 matchday: 'Match day A', 'matchday-b': 'Match day B', sailkapena: 'Clasificación (SAILKAPENA)' };
const nombre = p => NOMBRE[p.tipo] || p.nombre;
const estado = p => marca(p) === 'publicada' ? 'publicada ✅'
  : marca(p) === 'descartada' ? 'esta semana no 🚫 (se puede pedir con /publicar)'
  : p.lista ? 'lista para publicar 🟢' : `no lista ⏳ (falta: ${(p.faltan || []).join('; ')})`;

// ---------- botones
// ---------- noticias desde Instagram (botones «nsi/nno:id» y «web/nweb:id»)
const cbN = upd.callback_query;
if (cbN && /^(nsi|nno|web|nweb):/.test(String(cbN.data))) {
  const [accion, id] = String(cbN.data).split(':');
  const original = String((cbN.message && cbN.message.text) || '');
  const marcar = nota => ({ accion: 'quitar_botones', messageId: cbN.message && cbN.message.message_id,
    texto: original.replace(/\n?¿La ponemos como noticia en la web\?$/, '').replace(/\nSi quieres otro[^\n]*$/, '') + `\n${nota}` });
  if (accion === 'nno') return salir(marcar('No es noticia'));
  if (accion === 'nweb') return salir(marcar('❌ Cancelado'));
  const titulo = accion === 'web' ? ((original.split(RAYA)[1] || '').trim()) : null;
  // Para proponer el título (nsi) o ponerla en la web (web) hace falta leer la publicación de Instagram
  return salir(marcar(accion === 'nsi' ? '✅ Sí, es noticia' : '⏳ Poniéndola en la web…'),
               { accion: 'leer_publicacion', id, siguiente: accion === 'nsi' ? 'titulo' : 'web', titulo });
}

// ---------- amistosos (botones «ams:…» Apuntar / «amn:…» Cancelar); los datos van en la línea «🆔 amistoso|…»
const cbA = upd.callback_query;
if (cbA && /^(ams|amn):/.test(String(cbA.data))) {
  const original = String((cbA.message && cbA.message.text) || '');
  const marcar = nota => ({ accion: 'quitar_botones', messageId: cbA.message && cbA.message.message_id,
    texto: original.replace(/\n?¿[^?\n]*\?$/, '') + `\n${nota}` });
  if (String(cbA.data).startsWith('amn:')) return salir(marcar('❌ Cancelado'));
  const linea = (original.match(/🆔 (amistoso\|[^\n]*)/) || [])[1];
  if (!linea) return salir(mensaje('🤔 No entiendo ese mensaje. Vuelve a escribir el comando.'));
  const [, que, ...d] = linea.split('|');
  const inputs = que === 'anadir' ? { accion: 'anadir', equipo: d[0], fecha: d[1], hora: d[2], fuera: d[3], rival: d[4], campo: d[5] || '' }
    : que === 'resultado' ? { accion: 'resultado', id: d[0], gl: d[1], gv: d[2] } : { accion: 'borrar', id: d[0] };
  return salir(marcar('⏳ Guardando en la web…'), { accion: 'amistoso_web', inputs });
}

// Cada botón lleva «acción:pieza:semana». Antes de llegar aquí, el nodo «Cada botón una sola vez» ya ha
// descartado los repetidos: un mismo «Publicar» (o «Subir historia») de una pieza solo pasa una vez por semana.
const cb = upd.callback_query;
if (cb) {
  const [accion, tipo, semana] = String(cb.data || '').split(':');
  const p = pieza(tipo);
  if (!p || p.semana !== semana) return salir(mensaje('Esa publicación ya no está disponible (es de otra semana).'));
  // «🚫 Esta semana no» (en la foto): no se vuelve a ofrecer esta semana
  if (accion === 'des') {
    if (marca(p) === 'publicada') return salir(mensaje(`✅ ${nombre(p)} ya está publicada esta semana.`));
    return salir(apuntar(p, 'descartada'),
      mensaje(`🚫 ${nombre(p)}: no se volverá a ofrecer esta semana.\nSi cambias de idea: /publicar ${PEDIR[p.tipo] || p.tipo}`));
  }
  const original = String((cb.message && cb.message.text) || '');
  // Deja el mensaje sin botones y con una marca de lo que se ha hecho
  const quitarBotones = nota => {
    const resto = original.replace(/\n?¿(Publico con este texto|Subo también la historia[^?]*|Lo intento otra vez)\?$/, '');
    return { accion: 'quitar_botones', messageId: cb.message && cb.message.message_id,
             texto: resto ? `${resto}\n${nota}` : `Historia de ${p.nombre}: ${nota}` };
  };
  // Publicar (o reintentar, «rep») → sección 4, que publica en Instagram y luego pregunta por la historia
  if (accion === 'pub' && marca(p) === 'publicada') return salir(quitarBotones('✅ Ya estaba publicada esta semana: no se publica otra vez.'));
  if (accion === 'pub' || accion === 'rep') {
    const texto = (original.split(RAYA)[1] || '').trim();
    return salir(quitarBotones('⏳ Publicando en Instagram…'),
      { accion: 'publicar_ig', formato: 'post', tipo, semana, nombre: p.nombre, imagen: p.post, caption: texto, carrusel: p.carrusel || null,
        // En un reintento, la hora del mensaje de error: por si aquel intento sí llegó a publicarse
        fallo: accion === 'rep' && cb.message ? cb.message.date : null });
  }
  if (accion === 'can') return salir(quitarBotones('❌ Cancelado'),
    mensaje(`❌ Cancelado. Para poner otro texto, responde otra vez a la foto de ${p.nombre}.`));
  if (accion === 'his' || accion === 'reh') return salir(quitarBotones('⏳ Subiendo la historia…'),
    { accion: 'publicar_ig', formato: 'historia', tipo, semana, nombre: p.nombre, imagen: p.historia });
  if (accion === 'nohis') return salir(quitarBotones('no se sube'));
  if (accion === 'nre') return salir(quitarBotones('❌ Cancelado'));
  return [];
}

// ---------- mensajes
const msg = upd.message;
if (!msg || !msg.text) return [];
const texto = msg.text.trim();

// Respuesta a un mensaje del bot con «🆔 ig:» → es otro título para la noticia
const citada = msg.reply_to_message;
const ig = citada && citada.from && citada.from.is_bot && String(citada.text || '').match(/🆔 ig:(\S+)/);
if (ig) return salir({ accion: 'proponer_titulo', id: ig[1], titulo: texto });

// Respuesta citando una foto del bot → es el texto de la publicación. La pieza va en la línea «🆔».
if (citada && citada.from && citada.from.is_bot && citada.photo) {
  const m = String(citada.caption || '').match(/🆔\s*([a-z-]+)/);
  const p = m && pieza(m[1]);
  if (!p) return salir(mensaje('🤔 No sé de qué publicación es esa foto (puede ser de otra semana). Escribe /publicar y la publicación (por ejemplo /publicar match day A) y responde a la foto nueva.'));
  if (texto.length > 2200) return salir(mensaje(`El texto tiene ${texto.length} caracteres y Instagram admite 2200. Acórtalo y vuelve a responder a la foto.`));
  return salir({ accion: 'mensaje_botones',
    texto: `📝 ${p.nombre}\n${RAYA}\n${texto}\n${RAYA}\n¿Publico con este texto?`,
    boton1: '✅ Publicar', dato1: `pub:${p.tipo}:${p.semana}`, boton2: '❌ Cancelar', dato2: `can:${p.tipo}:${p.semana}` });
}

// Comandos (en castellano; también valen los nombres en euskera de las imágenes)
if (!texto.startsWith('/')) return [];
const [orden, ...resto] = texto.split(/\s+/);
const comando = orden.split('@')[0].toLowerCase();
// «match day A», «matchday-b», «resultados»… → la pieza de ultimo.json
const QUE = { horarios: 'ordutegia', ordutegia: 'ordutegia', resultados: 'emaitzak', emaitzak: 'emaitzak',
              matchdaya: 'matchday', matchday: 'matchday', a: 'matchday', matchdayb: 'matchday-b', b: 'matchday-b',
              clasificacion: 'sailkapena', sailkapena: 'sailkapena' };
const cual = QUE[resto.join('').toLowerCase().replace(/[^a-z]/g, '')];
const verPieza = p => ({ accion: 'foto', foto: p.post, texto: `${nombre(p)}: ${estado(p)}` });
// Un carrusel se ve entero: la portada y después el resto
const verTodo = p => [verPieza(p), ...(p.carrusel || []).slice(1).map((foto, i) => ({ accion: 'foto', foto, texto: `${nombre(p)} · ${i + 2}/${p.carrusel.length}` }))];
const lista = Object.values(piezas);

if (comando === '/estado') {
  if (!lista.length) return salir(mensaje('Esta semana no hay ninguna publicación con datos.'));
  return salir(mensaje('📋 Publicaciones de esta semana:\n' + lista.map(p => `• ${nombre(p)}: ${estado(p)}`).join('\n')));
}
const VER = { '/horarios': ['ordutegia'], '/ordutegia': ['ordutegia'], '/resultados': ['emaitzak'], '/emaitzak': ['emaitzak'],
              '/matchday': ['matchday', 'matchday-b'], '/clasificacion': ['sailkapena'], '/sailkapena': ['sailkapena'] };
if (VER[comando]) {
  const elegidas = VER[comando].map(pieza).filter(Boolean);
  return elegidas.length ? salir(...elegidas.flatMap(verTodo)) : salir(mensaje('Esta semana no hay esa publicación.'));
}
if (comando === '/publicar') {
  const p = cual && pieza(cual);
  if (!p) return salir(mensaje('¿Cuál? Escribe una de estas:\n/publicar horarios\n/publicar resultados\n/publicar match day A\n/publicar match day B\n/publicar clasificacion' +
    (cual ? '\n\n(Esa publicación no tiene datos esta semana.)' : '')));
  const VERLA = { ordutegia: '/horarios', emaitzak: '/resultados', matchday: '/matchday', 'matchday-b': '/matchday', sailkapena: '/clasificacion' };
  if (marca(p) === 'publicada') return salir(mensaje(`✅ ${nombre(p)} ya está publicada esta semana. Para verla: ${VERLA[p.tipo] || '/estado'}`));
  return salir({ accion: 'preguntar', pieza: p });
}
if (comando === '/revisar') return salir({ accion: 'revisar_instagram' });

// ---------- amistosos
const RAYA_A = '────────────';
const botones = (texto, linea, pregunta = '¿Lo apunto?') => ({ accion: 'mensaje_botones', texto: `${texto}\n🆔 ${linea}\n${pregunta}`,
  boton1: '✅ Apuntar', dato1: `ams:${Date.now().toString(36)}`, boton2: 'Cancelar', dato2: `amn:${Date.now().toString(36)}` });
const leerCat = palabras => {
  const t = palabras.map(w => w.toLowerCase());
  if (t[0] === 'senior' || t[0] === 'sénior') return t[1] === 'b' ? ['b', 2] : t[1] === 'a' ? ['primer', 2] : ['primer', 1];
  const una = { juvenil: 'juvenil', cadete: 'cadete', infantil: 'infantil', alevin: 'alevin', 'alevín': 'alevin' }[t[0]];
  return una ? [una, 1] : [null, 0];
};
if (comando === '/amistoso') {
  const [equipo, n] = leerCat(resto);
  const [dia, hora, ...mas] = resto.slice(n);
  const m = /^(\d{1,2})\/(\d{1,2})$/.exec(dia || '');
  const uso = '\n\nEjemplo: /amistoso infantil 24/10 10:30 Escolapios\nSi es fuera: /amistoso senior a 30/07 19:00 Barakaldo fuera en Lasesarre';
  if (!equipo || !m || !/^\d{1,2}:\d{2}$/.test(hora || '') || !mas.length) return salir(mensaje('🤔 No lo he entendido.' + uso));
  // El año: este, salvo que la fecha ya haya pasado hace más de un mes (entonces, el que viene)
  const hoy = new Date(); let anio = hoy.getFullYear();
  const f = new Date(anio, +m[2] - 1, +m[1]); if (hoy - f > 30 * 864e5) anio++;
  const fecha = `${anio}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  const iFuera = mas.findIndex(w => w.toLowerCase() === 'fuera');
  const rival = (iFuera >= 0 ? mas.slice(0, iFuera) : mas).join(' ');
  const resto2 = iFuera >= 0 ? mas.slice(iFuera + 1) : [];
  const campo = resto2[0] && resto2[0].toLowerCase() === 'en' ? resto2.slice(1).join(' ') : '';
  if (!rival) return salir(mensaje('🤔 Falta el rival.' + uso));
  const fuera = iFuera >= 0;
  return salir(botones(`⚽ Amistoso\n${RAYA_A}\n${CATS[equipo]} · ${fechaLarga(fecha)} · ${hora.padStart(5, '0')}\n` +
    (fuera ? `${rival} – ${nombreNuestro(equipo)} · fuera${campo ? ' (' + campo + ')' : ' (campo sin poner: el MATCH DAY esperará al campo)'}` : `${nombreNuestro(equipo)} – ${rival} · en casa (Otxartaga)`) + `\n${RAYA_A}`,
    `amistoso|anadir|${equipo}|${fecha}|${hora.padStart(5, '0')}|${fuera ? 'si' : 'no'}|${rival}|${campo}`));
}
if (comando === '/resultado') {
  const [equipo, n] = leerCat(resto);
  const r = /^(\d{1,2})-(\d{1,2})$/.exec(resto.slice(n).join('') || '');
  if (!equipo || !r) return salir(mensaje('🤔 No lo he entendido. Ejemplo: /resultado infantil 3-1 (primero los goles del que juega en casa).'));
  const hoyIso = new Date().toISOString().slice(0, 10);
  const a = AMISTOSOS.filter(x => x.equipo === equipo && x.gl == null && x.fecha <= hoyIso).pop();
  if (!a) return salir(mensaje(`No hay ningún amistoso del ${CATS[equipo]} ya jugado y sin resultado. Mira la lista con /amistosos.`));
  return salir(botones(`⚽ Resultado del amistoso\n${RAYA_A}\n${CATS[equipo]} · ${fechaLarga(a.fecha)}\n${marcador(a, r[1], r[2])}\n${RAYA_A}`,
    `amistoso|resultado|${a.id}|${r[1]}|${r[2]}`));
}
if (comando === '/amistosos') {
  if (!AMISTOSOS.length) return salir(mensaje('No hay amistosos apuntados. Para apuntar uno: /amistoso infantil 24/10 10:30 Escolapios'));
  return salir(mensaje('⚽ Amistosos apuntados:\n' + AMISTOSOS.map((a, i) => `${i + 1}. ${CATS[a.equipo]} · ${a.fecha.slice(8)}/${a.fecha.slice(5, 7)} ${a.hora || ''} · ` +
    (a.gl != null ? marcador(a, a.gl, a.gv) : (a.casa ? `${nombreNuestro(a.equipo)} – ${a.rival}` : `${a.rival} – ${nombreNuestro(a.equipo)}`))).join('\n') +
    '\n\nPara quitar uno: /borrar amistoso 2 (el número de la lista).'));
}
if (comando === '/borrar') {
  const num = parseInt(resto[resto.length - 1], 10);
  const a = AMISTOSOS[num - 1];
  if (!/^amistoso/i.test(resto[0] || '') || !a) return salir(mensaje('🤔 Escribe /borrar amistoso y el número de la lista de /amistosos (por ejemplo: /borrar amistoso 2).'));
  return salir({ ...botones(`🗑️ Borrar amistoso\n${RAYA_A}\n${CATS[a.equipo]} · ${fechaLarga(a.fecha)} · ${a.casa ? nombreNuestro(a.equipo) + ' – ' + a.rival : a.rival + ' – ' + nombreNuestro(a.equipo)}\n${RAYA_A}`,
    `amistoso|borrar|${a.id}`, '¿Lo borro?'), boton1: '🗑️ Borrar' });
}
if (comando === '/instagram') return salir({ accion: 'comprobar_instagram' });
if (comando === '/probar' && cual === undefined && resto.join(' ').toLowerCase() === 'noticia') {
  return salir({ accion: 'nueva_publicacion', publicacion: { id: 'prueba' + Date.now().toString(36), prueba: true,
    caption: '¡Homenaje a nuestros veteranos este sábado!\n\nA las 12:00 en Otxartaga Berri, antes del partido del Senior A. Os esperamos a todos 💙🤍\n\n#aupaortuella',
    media_type: 'IMAGE', media_url: 'https://lehendakari02.github.io/web-cd-ortuella/img/campo.jpg',
    permalink: 'https://www.instagram.com/cdortuella/', timestamp: new Date().toISOString() } });
}
const AYUDA = {
  ver: '👀 VER\n/estado → qué publicaciones están listas y qué les falta\n/horarios · /resultados · /matchday · /clasificacion → ver las imágenes de esta semana',
  publicar: '📣 PUBLICAR EN INSTAGRAM\nCada publicación lista sale en cada revisión (8:30 y 23:30) hasta que se publique. Para escribir el texto: mantén pulsada su foto → Responder, y escríbelo. Luego, Publicar o Cancelar, y si se sube la historia.\n🚫 Esta semana no (botón de la foto) → no vuelve a salir esta semana\n/publicar horarios · resultados · match day A · match day B · clasificacion → pedirla aunque no esté lista (o aunque la hayas descartado)',
  amistosos: '⚽ AMISTOSOS (los que no publica la Federación)\n/amistoso infantil 24/10 10:30 Escolapios → apuntar uno en casa\n/amistoso senior a 30/07 19:00 Barakaldo fuera en Lasesarre → fuera, con su campo\n/resultado infantil 3-1 → resultado del último jugado (primero los goles del de casa)\n/amistosos → lista numerada\n/borrar amistoso 2 → quitar el número 2 de la lista\nSalen en horarios, match day, resultados, la web y el calendario; no cuentan para la clasificación.',
  noticias: '📰 NOTICIAS DE LA WEB\nCada hora el bot mira si hay publicaciones nuevas en Instagram y pregunta si son noticia (Sí / No).\n/revisar instagram → mirarlo ya\n/probar noticia → prueba que no cambia la web',
  instagram: '🔌 INSTAGRAM\n/instagram → comprobar que el bot está conectado (también lo vigila solo cada día)',
};
if (comando === '/ayuda' || comando === '/start') {
  const bloque = AYUDA[(resto[0] || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')];
  if (bloque) return salir(mensaje(bloque));
  return salir(mensaje('🤖 Lo que sabe hacer el bot\n\n' + Object.values(AYUDA).join('\n\n') +
    '\n\nPara ver solo una parte: /ayuda amistosos (o ver, publicar, noticias, instagram).'));
}
return [];

// Llega cada hora (programado) o con /revisar instagram (a mano): a mano, siempre se contesta algo
const manual = $('¿Revisar Instagram?').isExecuted;
const r = $input.first().json;
const cuenta = (r.data || []).map(p => p.instagram_business_account).find(Boolean);
if (!cuenta) {
  const motivo = r.error ? (r.error.message || 'error de Meta') : 'el token no tiene acceso a la cuenta de Instagram del club';
  return manual ? [{ json: { accion: 'mensaje', texto: `🔌 Instagram no está conectado con el bot (${motivo}).` } }] : [];
}
return [{ json: { manual, ig: cuenta.id } }];

// Una por publicación, solo las de los últimos 3 días, con su clave de la memoria («ig:id»).
// La primera vez que se usa la memoria se apuntan como vistas sin ofrecerlas (si no, ofrecería como noticia
// lo que ya ha publicado el propio bot).
const desde = Date.now() - 3 * 864e5;
const recientes = ($('Leer publicaciones de Instagram').first().json.data || []).filter(p => new Date(p.timestamp) >= desde);
if (!$input.all().some(i => i.json.clave === 'ig:estreno'))
  return [{ json: { clave: 'ig:estreno', estado: 'hecho' } }, ...recientes.map(p => ({ json: { clave: `ig:${p.id}`, estado: 'vista' } }))]
    .map(i => ({ json: { ...i.json, accion: 'memoria' } }));
return recientes.map(publicacion => ({ json: { id: publicacion.id, publicacion, accion: 'memoria', clave: `ig:${publicacion.id}`, estado: 'ofrecida' } }));

// Las publicaciones nuevas siguen (y se apuntan en la memoria); si no hay ninguna y se ha pedido a mano, se dice
const todas = $input.all().filter(i => i.json.clave);
const nuevas = todas.filter(i => i.json.publicacion);
const manual = $('¿Instagram conectado?').first().json.manual;
if (nuevas.length || !manual) return todas;
return [...todas, { json: { accion: 'mensaje', texto: '🔎 No hay publicaciones nuevas en Instagram (de los últimos 3 días) que no se hayan ofrecido ya.' } }];

// Foto + mensaje con «¿La ponemos como noticia en la web?». La línea «🆔 ig:» dice qué publicación es.
const foto = p => p.media_type === 'VIDEO' ? p.thumbnail_url
  : p.media_type === 'CAROUSEL_ALBUM' ? (((p.children || {}).data || []).map(h => h.media_type === 'VIDEO' ? h.thumbnail_url : h.media_url).find(Boolean) || p.media_url)
  : p.media_url;
// (la pregunta sale como respuesta a su foto: si llegan varias a la vez, se sabe cuál va con cuál)
return $input.all().filter(item => item.json.publicacion).map(item => {
  const p = item.json.publicacion;
  const dia = new Date(p.timestamp).toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', timeZone: 'Europe/Madrid' });
  const pie = String(p.caption || '(sin texto)');
  const corto = pie.length > 700 ? pie.slice(0, 700) + '…' : pie;
  return { json: { foto: foto(p), textoFoto: `📰 Nueva publicación en Instagram (${dia})`,
    texto: `📰 ${corto}\n\n🆔 ig:${p.id}\n¿La ponemos como noticia en la web?`,
    boton1: '✅ Sí, es noticia', dato1: `nsi:${p.id}`, boton2: 'No', dato2: `nno:${p.id}` } };
});

// Las publicaciones de prueba (/probar noticia) no existen en Instagram: se rellenan aquí
return $input.all().map(item => item.json.id.startsWith('prueba')
  ? { json: { ...item.json, prueba: true, caption: '¡Homenaje a nuestros veteranos este sábado!\n\nA las 12:00 en Otxartaga Berri, antes del partido del Senior A. Os esperamos a todos 💙🤍\n\n#aupaortuella',
      media_type: 'IMAGE', media_url: 'https://lehendakari02.github.io/web-cd-ortuella/img/campo.jpg',
      permalink: 'https://www.instagram.com/cdortuella/', timestamp: new Date().toISOString() } }
  : item);

// Con la publicación ya leída: o se propone el título (tras «Sí») o se manda a la web (tras «Poner en la web»)
const RAYA = '────────────';
const ctx = $('Interpretar').all().map(x => x.json).find(x => x.accion === 'leer_publicacion') || {};
const p = $input.first().json;
const pie = String(p.caption || '');
// Título propuesto: la primera frase (o línea) del pie, sin emojis sueltos al final y como mucho 90 letras
const primera = (pie.split('\n').find(l => l.trim() && !l.trim().startsWith('#')) || 'Noticia del club').trim();
const frase = (primera.match(/^.*?[.!?](?=\s|$)/) || [primera])[0].replace(/[.]$/, '').trim();
const propuesto = frase.length > 90 ? frase.slice(0, 87).trimEnd() + '…' : frase;
if (ctx.siguiente === 'titulo') {
  return [{ json: { accion: 'mensaje_botones',
    texto: `📰 Título para la web:\n${RAYA}\n${propuesto}\n${RAYA}\n🆔 ig:${p.id || ctx.id}\nSi quieres otro título, responde a este mensaje con él.`,
    boton1: '✅ Poner en la web', dato1: `web:${p.id || ctx.id}`, boton2: 'Cancelar', dato2: `nweb:${p.id || ctx.id}` } }];
}
// A la web: si el título es la primera línea del pie, no se repite en el texto
const titulo = ctx.titulo || propuesto;
const empieza = titulo.replace(/…$/, '');
const texto = pie.trim().startsWith(empieza) && !titulo.endsWith('…')
  ? pie.trim().slice(empieza.length).replace(/^[.!?]?[ \t]*\n?/, '') : pie;
const foto = p.media_type === 'VIDEO' ? p.thumbnail_url
  : p.media_type === 'CAROUSEL_ALBUM' ? (((p.children || {}).data || []).map(h => h.media_type === 'VIDEO' ? h.thumbnail_url : h.media_url).find(Boolean) || p.media_url)
  : p.media_url;
return [{ json: { accion: 'enviar_a_web', prueba: p.prueba === true, titulo,
  inputs: { id: String(p.id || ctx.id), titulo, texto, fecha: String(p.timestamp).slice(0, 10),
            foto_url: foto, enlace: p.permalink || '', prueba: p.prueba === true } } }];

// GitHub contesta vacío si todo va bien; si hay error, se avisa en el grupo
const envio = $('Título o noticia').first().json;
const fallo = $input.first().json.error;
if (fallo) return [{ json: { accion: 'mensaje', texto: `⚠️ No se ha podido mandar «${envio.titulo}» a la web (${fallo.message || 'error de GitHub'}). Revisa la credencial de GitHub en n8n.` } }];
return [{ json: { accion: 'mensaje', texto: envio.prueba
  ? `🧪 (prueba) «${envio.titulo}» ha llegado al robot de GitHub, que lo ha preparado sin cambiar la web. Puedes verlo en GitHub → Actions → Añadir noticia.`
  : `✅ «${envio.titulo}» se está poniendo en la web: aparecerá en Noticias en 1-2 minutos.` } }];

const fallo = $input.first().json.error;
const que = $('¿Amistoso a la web?').first().json.inputs.accion;
if (fallo) return [{ json: { accion: 'mensaje', texto: `⚠️ No se ha podido guardar (${fallo.message || 'error de GitHub'}). Revisa la credencial de GitHub en n8n.` } }];
const hecho = { anadir: 'Apuntando', resultado: 'Apuntando el resultado', borrar: 'Borrando' }[que] || 'Guardando';
return [{ json: { accion: 'mensaje', texto: `⏳ ${hecho}… En 3-5 minutos estará en las imágenes, la web y el calendario. Compruébalo con /amistosos.` } }];

const RAYA = '────────────';
return $input.all().map(({ json: t }) => ({ json: { accion: 'mensaje_botones',
  texto: `📰 Título para la web:
${RAYA}
${t.titulo}
${RAYA}
🆔 ig:${t.id}
Si quieres otro título, responde a este mensaje con él.`,
  boton1: '✅ Poner en la web', dato1: `web:${t.id}`, boton2: 'Cancelar', dato2: `nweb:${t.id}` } }));

const RAYA = '────────────';
// Mensaje de error con «Reintentar» (el botón lleva la hora, así que es nuevo y «Cada botón una sola vez» lo deja pasar)
const fallo = (q, motivo) => ({ accion: 'mensaje_botones',
  texto: `⚠️ No se ha podido ${q.formato === 'historia' ? 'subir la historia' : 'publicar el post'} de ${q.nombre} en Instagram: ${motivo}` +
    (q.formato === 'historia' ? '' : `\n${RAYA}\n${q.caption}\n${RAYA}`) + '\n¿Lo intento otra vez?',
  boton1: '🔁 Reintentar', dato1: `${q.formato === 'historia' ? 'reh' : 'rep'}:${q.tipo}:${q.semana}:${Date.now().toString(36)}`,
  boton2: 'Cancelar', dato2: `nre:${q.tipo}:${q.semana}:${Date.now().toString(36)}` });
const q = $('¿Publicar en Instagram?').first().json;
const error = n => { try { const e = $(n).first().json.error; return e && (e.message || e.description || 'error de Meta'); } catch (_) { return null; } };
const cuenta = ($('Cuenta de Instagram (publicar)').first().json.data || []).map(p => p.instagram_business_account).find(Boolean);
if (!cuenta) return [{ json: fallo(q, error('Cuenta de Instagram (publicar)') || 'el token no tiene acceso a la cuenta de Instagram del club') }];
// Guardia de los reintentos: si al reintentar resulta que el intento fallido sí se publicó (mismo texto,
// publicado desde poco antes del mensaje de error), no se publica otra vez. Una publicación normal no se
// compara por texto: dos piezas distintas pueden llevar el mismo texto («Publicar» ya vale una vez por semana).
const ya = q.formato === 'post' && q.fallo && ($input.first().json.data || []).find(m =>
  String(m.caption || '').trim() === q.caption.trim() && new Date(m.timestamp) / 1000 >= q.fallo - 300);
if (ya) return [{ json: { accion: 'mensaje', texto: `✅ El post de ${q.nombre} ya estaba publicado: ${ya.permalink}` } }];
const cuerpo = q.formato === 'historia' ? { image_url: q.imagen, media_type: 'STORIES' } : { image_url: q.imagen, caption: q.caption };
// Carrusel: primero un contenedor por imagen y luego el del carrusel, que es el que se publica
if (q.formato === 'post' && (q.carrusel || []).length > 1)
  return q.carrusel.map(url => ({ json: { accion: 'crear_imagen', ig: cuenta.id, cuerpo: { image_url: url, is_carousel_item: true } } }));
return [{ json: { accion: 'crear', ig: cuenta.id, usuario: cuenta.username, cuerpo } }];

const RAYA = '────────────';
// Mensaje de error con «Reintentar» (el botón lleva la hora, así que es nuevo y «Cada botón una sola vez» lo deja pasar)
const fallo = (q, motivo) => ({ accion: 'mensaje_botones',
  texto: `⚠️ No se ha podido ${q.formato === 'historia' ? 'subir la historia' : 'publicar el post'} de ${q.nombre} en Instagram: ${motivo}` +
    (q.formato === 'historia' ? '' : `\n${RAYA}\n${q.caption}\n${RAYA}`) + '\n¿Lo intento otra vez?',
  boton1: '🔁 Reintentar', dato1: `${q.formato === 'historia' ? 'reh' : 'rep'}:${q.tipo}:${q.semana}:${Date.now().toString(36)}`,
  boton2: 'Cancelar', dato2: `nre:${q.tipo}:${q.semana}:${Date.now().toString(36)}` });
const q = $('¿Publicar en Instagram?').first().json;
const error = n => { try { const e = $(n).first().json.error; return e && (e.message || e.description || 'error de Meta'); } catch (_) { return null; } };
const motivo = error('Crear en Instagram') || error('Publicar en Instagram');
const id = $('Publicar en Instagram').first().json.id;
if (motivo || !id) return [{ json: fallo(q, motivo || 'Instagram no ha contestado') }];
const enlace = $input.first().json.permalink || '';
// En la memoria: lo que publica el bot no se ofrece después como noticia, y la pieza ya no se vuelve a ofrecer
const apuntar = { accion: 'memoria', clave: `ig:${id}`, estado: 'del bot' };
if (q.formato === 'historia') return [{ json: { accion: 'mensaje', texto: `✅ Historia de ${q.nombre} subida a Instagram.` } }, { json: apuntar }];
const p = { tipo: q.tipo, semana: q.semana };
const pieza = ($('Leer ultimo.json (bot)').first().json.piezas || {})[q.tipo] || {};
return [
  { json: { accion: 'mensaje', texto: `✅ Publicado en Instagram: ${q.nombre}${enlace ? '\n' + enlace : ''}` } },
  ...(pieza.historia ? [
    { json: { accion: 'foto', foto: pieza.historia, texto: `Historia de ${q.nombre}` } },
    { json: { accion: 'mensaje_botones', texto: `¿Subo también la historia de ${q.nombre}?`,
      boton1: '✅ Subir historia', dato1: `his:${p.tipo}:${p.semana}`, boton2: 'No', dato2: `nohis:${p.tipo}:${p.semana}` } }] : []),
  { json: apuntar }, { json: { accion: 'memoria', clave: `pieza:${q.tipo}-${q.semana}`, estado: 'publicada' } }];

const RAYA = '────────────';
// Mensaje de error con «Reintentar» (el botón lleva la hora, así que es nuevo y «Cada botón una sola vez» lo deja pasar)
const fallo = (q, motivo) => ({ accion: 'mensaje_botones',
  texto: `⚠️ No se ha podido ${q.formato === 'historia' ? 'subir la historia' : 'publicar el post'} de ${q.nombre} en Instagram: ${motivo}` +
    (q.formato === 'historia' ? '' : `\n${RAYA}\n${q.caption}\n${RAYA}`) + '\n¿Lo intento otra vez?',
  boton1: '🔁 Reintentar', dato1: `${q.formato === 'historia' ? 'reh' : 'rep'}:${q.tipo}:${q.semana}:${Date.now().toString(36)}`,
  boton2: 'Cancelar', dato2: `nre:${q.tipo}:${q.semana}:${Date.now().toString(36)}` });
const q = $('¿Publicar en Instagram?').first().json;
const error = n => { try { const e = $(n).first().json.error; return e && (e.message || e.description || 'error de Meta'); } catch (_) { return null; } };
// Si alguna imagen no se ha podido preparar, no se publica nada
const hechas = $input.all().map(i => i.json);
const mal = hechas.find(h => h.error || !h.id);
if (mal) return [{ json: fallo(q, (mal.error && (mal.error.message || 'error de Meta')) || 'Instagram no ha preparado una imagen del carrusel') }];
const ig = $('¿Ya publicada?').first().json.ig;
return [{ json: { accion: 'crear', ig, cuerpo: { media_type: 'CAROUSEL', children: hechas.map(h => h.id).join(','), caption: q.caption } } }];

const r = $input.first().json;
const cuenta = (r.data || []).map(p => p.instagram_business_account).find(Boolean);
return [{ json: { accion: 'mensaje', texto: cuenta
  ? `✅ Instagram conectado: @${cuenta.username}. El bot puede publicar y leer las publicaciones.`
  : `🔌 Instagram no está conectado (${r.error ? (r.error.message || 'error de Meta') : 'el token no tiene acceso a la cuenta de Instagram del club'}).` } }];

// Conectado → silencio. Si no, aviso (se repite cada día mientras siga sin arreglar)
const r = $input.first().json;
if ((r.data || []).some(p => p.instagram_business_account)) return [];
const motivo = r.error ? (r.error.message || 'error de Meta') : 'el token no tiene acceso a la cuenta de Instagram del club';
return [{ json: { accion: 'mensaje', texto: `⚠️ El bot ha perdido la conexión con Instagram (${motivo}). Hasta arreglarlo no se puede publicar ni leer las publicaciones. Escribe /instagram para comprobarlo.` } }];
